<script setup>
import {ref,computed} from 'vue'
import {useShots} from './shot-store.js'
const api=useShots(),q=ref(''),filter=ref('all');const rows=computed(()=>api.data.manifest.filter(s=>{const r=api.state.records[s.id]||{},state=r.hidden?'hidden':r.images?.length?'filled':'empty';return(filter.value==='all'||filter.value===state)&&(s.id+' '+s.group+' '+s.title).toLowerCase().includes(q.value.toLowerCase())}));function href(s){return s.route+'?edit=1#shot-'+s.id}
</script>
<template><article class="studio-lesson"><p class="eyebrow">YOUR SCREENSHOTS / YOUR VERSION</p><h1>一张一张补齐，<br>每一步都有依据。</h1><p class="lead">选择一个位置，进入具体步骤上传。没上传保持原样，取消选择不删图。共享软件截图与本站账户截图分别管理。</p><button class="gold-button" @click="api.state.editing=true">开始本机截图编辑</button><p v-if="api.state.unknown.length" class="edu-note">{{api.state.unknown.length}} 个旧图片位暂未找到当前位置，已保留在导出的备份中。请核对位置后手动迁移，不会静默删除。</p><div class="filter-bar"><input v-model="q" placeholder="搜索章节、步骤或图片位ID" aria-label="搜索截图位"><button v-for="[id,label] in [['all','全部'],['empty','待补图'],['filled','已上传'],['hidden','已隐藏']]" :key="id" @click="filter=id" :class="{active:filter===id}">{{label}}</button></div><p>{{rows.length}} 个匹配位置</p><div class="catalog"><a v-for="s in rows" :key="s.id" :href="href(s)" @click="api.state.editing=true"><div><small>{{s.group}} · {{s.section}}</small><h3>{{s.title}}</h3><p>{{s.target}}</p><code>{{s.id}}</code></div><span>{{api.state.records[s.id]?.hidden?'已隐藏':api.state.records[s.id]?.images?.length?'已上传':'待补图'}} →</span></a></div></article></template>
